<?php
require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Database.php';require_once __DIR__.'/../core/Response.php';Auth::requireLogin();$user=Auth::user();if(!Auth::isEmployee()&&!Auth::isAdmin()){http_response_code(403);exit('دسترسی غیرمجاز است.');}$pageTitle='نتایج KPI من';$rows=Database::fetchAll('SELECT t.title template_title,p.title period_title,ROUND(SUM(s.score*c.weight)/NULLIF(SUM(c.max_score*c.weight),0)*100,2) average_score,GROUP_CONCAT(CONCAT(c.criteria_text,": ",s.score,"/",c.max_score) SEPARATOR " | ") details FROM hr_kpi_scores s JOIN hr_kpi_templates t ON t.id=s.template_id JOIN hr_kpi_periods p ON p.id=s.period_id JOIN hr_kpi_criteria c ON c.id=s.criteria_id WHERE s.employee_id=? GROUP BY t.id,p.id ORDER BY p.sort_order DESC',[(int)$user['id']]);require __DIR__.'/../views/partials/admin-header.php';?>
<section class="card"><h1>نتایج ارزیابی عملکرد من</h1><div class="table-wrap"><table><thead><tr><th>قالب</th><th>دوره</th><th>امتیاز</th><th>جزئیات</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['template_title'])?></td><td><?=e($r['period_title'])?></td><td><?=e($r['average_score'])?>٪</td><td><details><summary>مشاهده</summary><?=e($r['details'])?></details></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="4">هنوز نتیجه‌ای برای شما ثبت نشده است.</td></tr><?php endif?></tbody></table></div></section>
</section></main></div><script src="/assets/js/app.js"></script></body></html>
